sys_script_include.script:
var ChangeSetService = Class.create();
ChangeSetService.DEFAULT_MATERIAL_PCT = 10;

ChangeSetService.prototype = {

    initialize: function () {
        this.C = Constants.CHOICE;
        this.T = Constants.TABLE;
    },

    // Compares the submission with its baseline policy version (Policy Snapshot)
    // and, optionally, PAS latest values keyed by canonical path.
    // opts: { pasValues: { '<canonical_path>': value } }
    build: function (submissionId, opts) {
        opts = opts || {};
        var sub = new GlideRecord(this.T.SUBMISSION);
        if (!sub.get(submissionId))
            throw new Error('[ChangeSetService] submission not found: ' + submissionId);
        var baseline = sub.getValue('baseline_policy_version');
        if (!baseline)
            throw new Error('[ChangeSetService] submission ' + sub.getValue('number') + ' has no baseline_policy_version');

        this._supersedeOpen(submissionId);
        var cs = new GlideRecord(this.T.CHANGE_SET);
        cs.initialize();
        cs.setValue('submission', submissionId);
        cs.setValue('baseline_policy_version', baseline);
        cs.setValue('purpose', sub.getValue('submission_type') === this.C.SUBMISSION_TYPE.RENEWAL ? this.C.CHANGE_SET_PURPOSE.RENEWAL : this.C.CHANGE_SET_PURPOSE.MTA);
        cs.setValue('status', this.C.CHANGE_SET_STATUS.DRAFT);
        var csId = cs.insert();

        var items = this._riskItems(baseline, submissionId).concat(this._coverageItems(baseline, submissionId));
        var pas = opts.pasValues || {};
        var threshold = this._threshold(baseline);
        var material = 0;
        for (var i = 0; i < items.length; i++) {
            var it = items[i];
            it.pas = pas[it.path] !== undefined ? String(pas[it.path]) : '';
            this._classify(it, threshold);
            if (it.material)
                material++;
            this._writeItem(csId, it);
        }

        cs.get(csId);
        cs.setValue('item_count', items.length);
        cs.setValue('material_count', material);
        cs.setValue('materiality', material ? this.C.MATERIALITY.MATERIAL :
            (this._anyChange(items) ? this.C.MATERIALITY.NON_MATERIAL : this.C.MATERIALITY.NONE));
        cs.setValue('status', this.C.CHANGE_SET_STATUS.EVALUATED);
        cs.setValue('evaluated_on', new GlideDateTime());
        cs.setValue('summary', this._summary(items, material, threshold));
        cs.update();

        sub.setValue('change_set', csId);
        sub.update();
        return csId;
    },

    // Policy snapshot risks (by insurable object) vs submission risks.
    _riskItems: function (baseline, submissionId) {
        var base = {}, cur = {}, out = [];
        var pr = new GlideRecord(this.T.POLICY_RISK);
        pr.addQuery('policy_version', baseline);
        pr.query();
        while (pr.next()) {
            var k = pr.getValue('insurable_object') || pr.getValue('location') || pr.getUniqueValue();
            base[k] = { label: pr.getValue('name'), value: parseFloat(pr.getValue('sum_insured')) || 0, id: pr.getUniqueValue(), table: this.T.POLICY_RISK };
        }
        var sr = new GlideRecord(this.T.SUBMISSION_RISK);
        sr.addQuery('submission', submissionId);
        sr.query();
        while (sr.next()) {
            var k2 = sr.getValue('insurable_object');
            cur[k2] = { label: sr.insurable_object.getDisplayValue(), value: parseFloat(sr.getValue('declared_value')) || 0, id: sr.getUniqueValue(), table: this.T.SUBMISSION_RISK };
        }
        return this._diff(base, cur, function (k, label) { return 'risks[' + label + '].declared_value'; });
    },

    // Bound terms vs requested terms - limits, deductibles, sublimits, retentions at
    // policy / line / jurisdiction / object level - keyed by coverage + term type +
    // basis + object + jurisdiction + peril, so a changed deductible on one vehicle or
    // a new flood sublimit on one location is its own change item.
    _coverageItems: function (baseline, submissionId) {
        var base = {}, cur = {};
        var pc = new GlideRecord(this.T.POLICY_COVERAGE_TERM);
        pc.addQuery('policy_version', baseline);
        pc.query();
        while (pc.next()) {
            var cov = pc.policy_coverage.coverage.toString();
            if (!cov) continue;
            var k = this._termKey(cov, pc.getValue('term_type'), pc.getValue('limit_basis'),
                pc.getValue('insurable_object') || pc.policy_coverage.insurable_object.toString(), pc.getValue('jurisdiction'), pc.getValue('cause_of_loss'));
            base[k] = { label: this._termLabel(pc.policy_coverage.coverage.getDisplayValue(), pc.getValue('term_type'), pc.getValue('limit_basis'), pc.insurable_object.getDisplayValue() || pc.policy_coverage.insurable_object.getDisplayValue()),
                value: this._amount(pc.getValue('selected_value'), pc.getValue('percentage')), id: pc.getValue('policy_coverage'), table: this.T.POLICY_COVERAGE };
        }
        var st = new GlideRecord(this.T.SUBMISSION_COVERAGE_TERM);
        st.addQuery('submission_coverage.submission', submissionId);
        st.query();
        var covered = {};
        while (st.next()) {
            var cov2 = st.submission_coverage.coverage.toString();
            if (!cov2) continue;
            covered[st.getValue('submission_coverage')] = true;
            var k2 = this._termKey(cov2, st.getValue('term_type'), st.getValue('limit_basis'),
                st.getValue('insurable_object') || st.submission_coverage.insurable_object.toString(), st.getValue('jurisdiction'), st.getValue('cause_of_loss'));
            cur[k2] = { label: this._termLabel(st.submission_coverage.coverage.getDisplayValue(), st.getValue('term_type'), st.getValue('limit_basis'), st.insurable_object.getDisplayValue() || st.submission_coverage.insurable_object.getDisplayValue()),
                value: this._amount(st.getValue('requested_value'), st.getValue('percentage')), id: st.getValue('submission_coverage'), table: this.T.SUBMISSION_COVERAGE };
        }
        // requested coverages without explicit terms: their limit / deductible columns
        var sc = new GlideRecord(this.T.SUBMISSION_COVERAGE);
        sc.addQuery('submission', submissionId);
        sc.query();
        while (sc.next()) {
            if (covered[sc.getUniqueValue()] || !sc.getValue('coverage')) continue;
            var pairs = [[this.C.POLICY_TERM_TYPE.LIMIT, 'requested_limit', sc.getValue('limit_basis')], [this.C.POLICY_TERM_TYPE.DEDUCTIBLE, 'requested_deductible', '']];
            for (var i = 0; i < pairs.length; i++) {
                if (sc.getValue(pairs[i][1]) === null || sc.getValue(pairs[i][1]) === '') continue;
                var k3 = this._termKey(sc.getValue('coverage'), pairs[i][0], pairs[i][2], sc.getValue('insurable_object'), sc.getValue('jurisdiction'), '');
                cur[k3] = { label: this._termLabel(sc.coverage.getDisplayValue(), pairs[i][0], pairs[i][2], sc.insurable_object.getDisplayValue()),
                    value: parseFloat(sc.getValue(pairs[i][1])) || 0, id: sc.getUniqueValue(), table: this.T.SUBMISSION_COVERAGE };
            }
        }
        return this._diff(base, cur, function (k, label) { return 'coverages[' + label + '].amount'; });
    },

    _termKey: function (coverage, type, basis, object, jurisdiction, peril) {
        return [coverage, type || '', basis || '', object || '', jurisdiction || '', peril || ''].join('|');
    },

    _termLabel: function (coverage, type, basis, objectLabel) {
        return coverage + ' / ' + (type || 'term') + (basis ? ' ' + basis : '') + (objectLabel ? ' @ ' + objectLabel : '');
    },

    // percentage terms (e.g. 2% wind deductible) compare on the percentage
    _amount: function (value, pct) {
        if (pct !== null && pct !== undefined && pct !== '')
            return parseFloat(pct) || 0;
        return parseFloat(value) || 0;
    },

    _diff: function (base, cur, pathFn) {
        var out = [], k;
        for (k in base) {
            if (!base.hasOwnProperty(k)) continue;
            var b = base[k], c = cur[k];
            out.push({
                path: pathFn(k, b.label), label: b.label,
                table: c ? c.table : b.table, record: c ? c.id : b.id,
                baseline: b.value, submission: c ? c.value : '',
                type: !c ? this.C.CHANGE_TYPE.REMOVED : (b.value === c.value ? this.C.CHANGE_TYPE.UNCHANGED : this.C.CHANGE_TYPE.MODIFIED)
            });
        }
        for (k in cur) {
            if (!cur.hasOwnProperty(k) || base[k]) continue;
            out.push({ path: pathFn(k, cur[k].label), label: cur[k].label, table: cur[k].table, record: cur[k].id,
                baseline: '', submission: cur[k].value, type: this.C.CHANGE_TYPE.ADDED });
        }
        return out;
    },

    _classify: function (it, threshold) {
        it.delta = '';
        it.material = false;
        it.reason = '';
        if (it.type === this.C.CHANGE_TYPE.ADDED || it.type === this.C.CHANGE_TYPE.REMOVED) {
            it.material = true;
            it.reason = it.type + ' since the policy snapshot';
        } else if (it.type === this.C.CHANGE_TYPE.MODIFIED) {
            it.delta = it.baseline ? Math.round((it.submission - it.baseline) / it.baseline * 10000) / 100 : 100;
            it.material = Math.abs(it.delta) >= threshold;
            it.reason = 'value changed ' + it.delta + '% (threshold ' + threshold + '%)';
        }
        if (it.pas !== '' && String(it.pas) !== String(it.baseline)) {
            it.material = true;
            it.reason += (it.reason ? '; ' : '') + 'PAS latest differs from the policy snapshot';
        }
    },

    _writeItem: function (csId, it) {
        var ci = new GlideRecord(this.T.CHANGE_ITEM);
        ci.initialize();
        ci.setValue('change_set', csId);
        ci.setValue('canonical_path', it.path);
        ci.setValue('entity_label', it.label);
        ci.setValue('table_name', it.table);
        ci.setValue('record_sys_id', it.record);
        ci.setValue('baseline_value', String(it.baseline));
        ci.setValue('pas_value', it.pas);
        ci.setValue('submission_value', String(it.submission));
        ci.setValue('change_type', it.type);
        ci.setValue('delta_pct', it.delta);
        ci.setValue('is_material', it.material);
        ci.setValue('materiality_reason', it.reason);
        ci.setValue('decision', this.C.CHANGE_DECISION.PENDING);
        ci.insert();
    },

    _threshold: function (baselineVersionId) {
        var v = new GlideRecord(this.T.POLICY_VERSION);
        if (v.get(baselineVersionId)) {
            var p = new GlideRecord(this.T.POLICY);
            if (p.get(v.getValue('policy'))) {
                var rule = new RenewalDecisionService().findRule(p);
                if (rule && rule.material_change_pct !== '')
                    return parseFloat(rule.material_change_pct);
            }
        }
        return ChangeSetService.DEFAULT_MATERIAL_PCT;
    },

    _supersedeOpen: function (submissionId) {
        var cs = new GlideRecord(this.T.CHANGE_SET);
        cs.addQuery('submission', submissionId);
        cs.addQuery('status', '!=', this.C.CHANGE_SET_STATUS.SUPERSEDED);
        cs.query();
        while (cs.next()) {
            cs.setValue('status', this.C.CHANGE_SET_STATUS.SUPERSEDED);
            cs.update();
        }
    },

    _anyChange: function (items) {
        for (var i = 0; i < items.length; i++)
            if (items[i].type !== this.C.CHANGE_TYPE.UNCHANGED) return true;
        return false;
    },

    _summary: function (items, material, threshold) {
        var counts = {};
        for (var i = 0; i < items.length; i++)
            counts[items[i].type] = (counts[items[i].type] || 0) + 1;
        var parts = [];
        for (var k in counts)
            if (counts.hasOwnProperty(k)) parts.push(counts[k] + ' ' + k);
        return items.length + ' compared (' + parts.join(', ') + '); ' + material + ' material at ' + threshold + '% threshold.';
    },

    type: 'ChangeSetService'
};
